import React from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ items, onBuy, purchasedItems }) {
  // 1. Get the current user ID from the token
  const token = localStorage.getItem("token");
  let currentUserId = null;

  if (token) {
    try {
      const decoded = jwtDecode(token);
      currentUserId = decoded._id; // Ensure this matches your token's key (_id or id)
    } catch (err) {
      console.error("Token decoding failed", err);
    }
  }

  // 2. Filter items so the user doesn't see their own books
  // Note: Replace 'sellerId' with the actual field name in your book object 
  // (e.g., item.userId, item.owner, or item.seller)
  const availableItems = items.filter((item) => item.sellerId !== currentUserId);

  return (
    <>
      <Navbar />
      <div className="Body">
        {availableItems.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '50px' }}>
            <p>No books available for purchase right now.</p>
          </div>
        ) : (
          availableItems.map((item) => (
            <Card 
              key={item._id || item.id} 
              pic={item.pic} 
              title={item.title} 
              para={item.para} 
              price={item.price}
            >
              <button
                onClick={() => onBuy(item)}
                disabled={!!purchasedItems[item._id || item.id]}
                style={{
                  backgroundColor: purchasedItems[item._id || item.id] ? "grey" : "rgba(13, 110, 264, 1)",
                  color: "#fff",
                  borderRadius: "5px",
                  padding: "5px",
                  fontWeight: "100",
                  fontFamily: "Century Gothic",
                  width: "130px",
                  border: "none",
                  cursor: purchasedItems[item._id || item.id] ? "default" : "pointer"
                }}
              >
                {purchasedItems[item._id || item.id] ? "Sold" : "Add to Cart"}
              </button>
            </Card>
          ))
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
